const fs = require('fs'), path = require('path'), os = require('os'), cp = require('child_process'), crypto = require('crypto');
const ROOT = process.env.RN_ALPS_HOME || path.join(process.env.USERPROFILE || os.homedir(), 'ReadNow', 'alps');
try { fs.mkdirSync(ROOT, { recursive: true }); } catch (e) {}
const F = { cfg: path.join(ROOT, 'config.json'), cred: path.join(ROOT, 'cred.dat'), credMeta: path.join(ROOT, 'cred-meta.json'), win: path.join(ROOT, 'win.txt'), key: path.join(ROOT, 'key.dat'), runs: path.join(ROOT, 'runs.json'), hist: path.join(ROOT, 'hist.json'), jobs: path.join(ROOT, 'jobs.json'), journal: path.join(ROOT, 'journal.json'), lastJob: path.join(ROOT, 'last-job.json'), log: path.join(ROOT, 'alps.log'), up: path.join(ROOT, 'up'), chrome: path.join(ROOT, 'chrome') };
